mapper.select:
SELECT * FROM interface_level 
WHERE interface_path = #{path} 
AND interface_method = #{method}
AND status = 1

mapper.insert:
INSERT INTO interface_level (
    interface_path, interface_method, allowed_levels, description, status
) VALUES (
    #{interfacePath}, #{interfaceMethod}, #{allowedLevels}, #{description}, #{status}
)

mapper.update:
UPDATE interface_level
interface_path = #{interfacePath}, interface_method = #{interfaceMethod}, allowed_levels = #{allowedLevels}, description = #{description}, status = #{status},
WHERE id = #{id}
